param([string]$OutFile='evidence/issue-50/pinned-versions-audit.json',[string]$GeneratedAt='')
$ErrorActionPreference='Stop';$root=(Get-Location).Path;$base=(git rev-parse HEAD).Trim();$registry='source/registry/runtime-versions.json'
$r=Get-Content $registry -Raw|ConvertFrom-Json;$pins=@(
 [pscustomobject]@{key='runtimes.v1';package=$r.runtimes.v1.package;version=$r.runtimes.v1.version;spec=$r.runtimes.v1.spec},
 [pscustomobject]@{key='runtimes.v2';package=$r.runtimes.v2.package;version=$r.runtimes.v2.version;spec=$r.runtimes.v2.spec},
 [pscustomobject]@{key='plugins.v1';package=$r.plugins.v1.package;version=$r.plugins.v1.version;spec=$r.plugins.v1.spec},
 [pscustomobject]@{key='plugins.v2';package=$r.plugins.v2.package;version=$r.plugins.v2.version;spec=$r.plugins.v2.spec},
 [pscustomobject]@{key='tools.bun';package=$r.tools.bun.package;version=$r.tools.bun.version;spec=$r.tools.bun.spec})
$scope=@('scripts/','plugins/','templates/','install.ps1','uninstall.ps1','source/registry/');$excluded=@('evidence/','docs/','cache/','.git/','node_modules/')
