$manualComments=@('plugins/orchestration-enforcement/shared/planner-wait.ts:243','plugins/orchestration-enforcement/shared/planner-wait.ts:344','plugins/orchestration-enforcement/shared/planner-wait.ts:414','plugins/orchestration-enforcement/v2.ts:164','plugins/orchestration-enforcement/v2.ts:177','scripts/ci/session-real-lane-v2.ps1:2968','scripts/v3/lib/OrchestrationModelRouter.ps1:2551','scripts/v3/lib/OrchestrationModelRouter.ps1:2553','scripts/v3/opencode-v2-regression-gate.ps1:3')
$vals=@($pins.version|Select-Object -Unique);$hits=@();foreach($v in $vals){$hits+=git grep -nF -- $v -- scripts plugins templates install.ps1 uninstall.ps1 source/registry};$hits=@($hits|Where-Object {$_ -notmatch '^scripts/v3/audit-pinned-versions\.ps1:'}|Sort-Object -Unique);$literalRows=@();$unparseable=@()
foreach($hit in $hits){$parts=$hit -split ':',3;if($parts.Count -ne 3){$unparseable += [pscustomobject]@{record=$hit;reason='git grep output did not contain path:line:text'};continue};$path=$parts[0];$ln=[int]$parts[1];$ctx=$parts[2];$id="$path`:$ln";$class=if($path -eq $registry){'SOURCE_OF_TRUTH'}elseif($path.StartsWith('source/registry/')){'REGISTRY_RECORD'}elseif($path -like '*.tests.ps1'){'TEST_FIXTURE'}elseif($manualProducts.ContainsKey($id)){'PRODUCT_CODE'}elseif($manualComments -contains $id){'COMMENT_OR_DOC'}elseif($ctx.Trim() -match '^(#|//|\*|<#)'){'COMMENT_OR_DOC'}else{'UNCLASSIFIED_NEEDS_REVIEW'};$literal=($vals|Where-Object{$ctx.Contains($_)}|Select-Object -First 1);$literalRows += [pscustomobject]@{path=$path;line=$ln;literal=$literal;context=$ctx.Trim();classification=$class}}
$comparators=@();$searchHits=@();$comparatorSearch=@{scope='scripts/, plugins/, templates/, install.ps1, uninstall.ps1, source/registry/';needles=@('[version]','CompareTo','semver');excluded='*.tests.ps1';matches=0;comparator_matches=0;method='Directed keyword search; search hits are manually distinguished from actual comparison expressions. No broad -ge/-lt scan.'}
$codeFiles=@();foreach($s in $scope){if(Test-Path $s){if((Get-Item $s).PSIsContainer){$codeFiles+=Get-ChildItem $s -File -Recurse}else{$codeFiles+=Get-Item $s}}};foreach($f in $codeFiles){if($f.Name -like '*.tests.ps1' -or $f.FullName -eq (Join-Path $root 'scripts/v3/audit-pinned-versions.ps1')){continue};$rel=$f.FullName.Substring($root.Length+1).Replace('\','/');$lineNo=0;foreach($line in [IO.File]::ReadLines($f.FullName)){$lineNo++;foreach($needle in $comparatorSearch.needles){if($line.Contains($needle)){$searchHits += [pscustomobject]@{path=$rel;line=$lineNo;needle=$needle;context=$line.Trim();actual_comparator=$false}}}}};$comparatorSearch.matches=$searchHits.Count;$comparatorSearch.comparator_matches=$comparators.Count
foreach($id in $manualProducts.Keys){if(-not ($literalRows|Where-Object{"$($_.path):$($_.line)" -eq $id})){$unparseable += [pscustomobject]@{path=($id -split ':')[0];line=[int](($id -split ':')[1]);reason='Manually reviewed product-code anchor absent from git-grep hits';classification='UNPARSEABLE'}}else{$literalRows|Where-Object{"$($_.path):$($_.line)" -eq $id}|%{$_.classification='PRODUCT_CODE'}}}
foreach($id in $manualComments){if(-not ($literalRows|Where-Object{"$($_.path):$($_.line)" -eq $id})){$unparseable += [pscustomobject]@{path=($id -split ':')[0];line=[int](($id -split ':')[1]);reason='Manually reviewed comment anchor absent from git-grep hits';classification='UNPARSEABLE'}}else{$literalRows|Where-Object{"$($_.path):$($_.line)" -eq $id}|%{$_.classification='COMMENT_OR_DOC'}}}
$literalRows=@($literalRows|Sort-Object path,line -Unique);$counts=[pscustomobject]@{distinct_literals=$vals.Count;path_lines=$literalRows.Count;SOURCE_OF_TRUTH=@($literalRows|? classification -eq SOURCE_OF_TRUTH).Count;REGISTRY_RECORD=@($literalRows|? { $_.path.StartsWith('source/registry/') }).Count;TEST_FIXTURE=@($literalRows|? classification -eq TEST_FIXTURE).Count;COMMENT_OR_DOC=@($literalRows|? classification -eq COMMENT_OR_DOC).Count;PRODUCT_CODE=@($literalRows|? classification -eq PRODUCT_CODE).Count;UNCLASSIFIED_NEEDS_REVIEW=@($literalRows|? classification -eq UNCLASSIFIED_NEEDS_REVIEW).Count;comparators=$comparators.Count}
$protected=@();foreach($p in @('templates/opencode.v1.json.tmpl','templates/opencode.v2.json.tmpl','source/agents','source/global/AGENTS.md','source/adapters')){if(Test-Path $p){$i=Get-Item $p;if($i.PSIsContainer){$fs=Get-ChildItem $p -File -Recurse}else{$fs=@($i)};foreach($f in $fs){$rel=$f.FullName.Substring($root.Length+1).Replace('\','/');$protected += [pscustomobject]@{path=$rel;sha256=(Get-FileHash $f.FullName -Algorithm SHA256).Hash}}}}
$now=if($GeneratedAt){$GeneratedAt}else{(Get-Date).ToUniversalTime().ToString('o')};$o=[pscustomobject]@{scan_scope=$scope;excluded_paths=$excluded;declared_pins=$pins;distinct_literals=$vals;literals=$literalRows;counts=$counts;reviewed_product_code=@(foreach($id in $manualProducts.Keys){[pscustomobject]@{path=($id -split ':')[0];line=[int](($id -split ':')[1]);rationale=$manualProducts[$id]}});reviewed_comment_or_doc=@($manualComments|%{$q=$_ -split ':';[pscustomobject]@{path=$q[0];line=[int]$q[1]}});comparators=$comparators;comparator_search=$comparatorSearch;comparator_search_hits=$searchHits;unparseable=$unparseable;protected_files=$protected;method=[pscustomobject]@{mode='git_grep_fixed_literal_path_line_dedup';no_model_call=$true;base_revision=$base;generated_by_commit=$base;limitations='Literal search does not detect dynamically assembled versions; semantic comparators are found only by directed keyword search.'};generated_at=$now};$dest=Join-Path $root $OutFile;New-Item -ItemType Directory -Force (Split-Path $dest)|Out-Null;$o|ConvertTo-Json -Depth 10|Set-Content -Encoding UTF8 $dest
